import flask
from flask import request, jsonify, render_template_string
import psycopg2
import os
import hashlib
import hmac

app = flask.Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'appuser')
DB_PASS = os.environ.get('DB_PASS', 'secret')

def get_db():
    return psycopg2.connect(
        host=DB_HOST, database=DB_NAME,
        user=DB_USER, password=DB_PASS
    )

@app.route('/search')
def search():
    query = request.args.get('q', '')
    category = request.args.get('cat', 'all')
    page = request.args.get('page', '1')

    # Input validation for pagination
    try:
        page_num = int(page)
        if page_num < 1:
            page_num = 1
    except ValueError:
        page_num = 1

    offset = (page_num - 1) * 20

    conn = get_db()
    cur = conn.cursor()

    # Build query based on category filter
    if category == 'all':
        sql = f"SELECT id, title, description, price FROM products WHERE title ILIKE '%{query}%' OR description ILIKE '%{query}%' ORDER BY id LIMIT 20 OFFSET {offset}"
    else:
        sql = f"SELECT id, title, description, price FROM products WHERE category = '{category}' AND (title ILIKE '%{query}%' OR description ILIKE '%{query}%') ORDER BY id LIMIT 20 OFFSET {offset}"

    try:
        cur.execute(sql)
        results = cur.fetchall()
    except Exception as e:
        conn.rollback()
        return jsonify({'error': 'Search failed'}), 500
    finally:
        cur.close()
        conn.close()

    products = []
    for row in results:
        products.append({
            'id': row[0],
            'title': row[1],
            'description': row[2],
            'price': float(row[3])
        })

    return jsonify({'results': products, 'page': page_num})

@app.route('/product/<int:product_id>')
def product_detail(product_id):
    conn = get_db()
    cur = conn.cursor()
    cur.execute("SELECT id, title, description, price, category FROM products WHERE id = %s", (product_id,))
    row = cur.fetchone()
    cur.close()
    conn.close()

    if not row:
        return jsonify({'error': 'Not found'}), 404

    return jsonify({
        'id': row[0],
        'title': row[1],
        'description': row[2],
        'price': float(row[3]),
        'category': row[4]
    })

@app.route('/health')
def health():
    try:
        conn = get_db()
        cur = conn.cursor()
        cur.execute("SELECT 1")
        cur.close()
        conn.close()
        return jsonify({'status': 'healthy'})
    except:
        return jsonify({'status': 'unhealthy'}), 503

@app.route('/admin/reindex', methods=['POST'])
def reindex():
    auth = request.headers.get('X-Internal-Token', '')
    expected = os.environ.get('INTERNAL_TOKEN', '')
    if not hmac.compare_digest(auth, expected):
        return jsonify({'error': 'unauthorized'}), 403

    conn = get_db()
    cur = conn.cursor()
    cur.execute("REINDEX TABLE products")
    conn.commit()
    cur.close()
    conn.close()
    return jsonify({'status': 'reindexed'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
